"use strict";
const TRANSLATIONS={"fr": {"choose": "Choisir la langue", "subtitle": "Feuille de score", "print": "Imprimer", "new": "Nouvelle partie", "history": "Historique", "history_title": "Historique des parties", "back": "Retour au jeu", "clear": "Effacer historique", "print_history": "🖨️ Imprimer historique", "normal": "1000 • normal", "double": "1500 • ♠ ♠", "team_a": "Équipe Nous", "team_b": "Équipe Eux", "us": "Nous", "them": "Eux", "names": "Mettez vos noms", "ann": "Annonces", "ann_title": "Annonces {name}", "round_points": "Points des donnes", "round": "Donne", "round_label": "Donne {number} {team}", "match": "Match", "help": "comment ça marche ?", "help_title": "Comment ça marche ?", "share": "Partager", "delete_question": "Supprimer cette partie ?", "yes": "Oui", "no": "Non", "validation": "Saisissez un nombre entier entre 2 et 155, ou 257 pour un match.", "full": "Les 12 donnes sont déjà remplies.", "win": "🏆 {name} a gagné ! {total} points", "empty": "Aucune partie enregistrée.", "winner": "Gagnant", "unfinished": "Partie terminée avant l’objectif", "unknown": "Gagnant non enregistré", "part": "Partie", "mode": "Mode", "points": "points", "pts": "pts", "delete_part": "Supprimer cette partie", "delete_number": "Supprimer la partie {number}", "share_part": "Partager cette partie", "share_number": "Partager la partie {number}", "clear_question": "Effacer définitivement tout l’historique des parties ?", "reset_question": "Nouvelle partie ?", "summary_copied": "Résumé de la partie copié !", "copy_summary": "Copiez le résumé de la partie :", "link_copied": "Lien copié !", "share_unavailable": "Le partage n’est pas disponible sur cet appareil.", "app_description": "Feuille de score Chibre installable sur téléphone.", "share_description": "Feuille de score Chibre", "card_title": "{rank} de {suit}", "nine": "Neuf", "jack": "Valet", "spade": "Pique (le plus fort)", "heart": "Cœur", "diamond": "Carreau", "club": "Trèfle (le plus faible)", "increase": "Ajouter {value} pour {team}", "decrease": "Retirer {value} pour {team}", "info": "Saisies autorisées : <b>2 à 155, ou 257 pour un match</b>. Une saisie de 257 donne <b>0 à l’autre équipe</b> et compte automatiquement un match. Sinon : <b>157 − points saisis</b>. En mode 1500, le total crédité est doublé une seule fois.", "help_start_title": "Commencer une partie", "help_start_body": "Inscrivez les noms des joueurs dans « Nous » et « Eux », puis choisissez le mode. La feuille affiche 8 donnes au départ. Si toutes les lignes affichées sont remplies et qu’aucune équipe n’a gagné, une nouvelle ligne apparaît, jusqu’à un maximum de 12 donnes. En mode 1000 normal, les points des donnes et des annonces comptent une fois ; l’objectif est de 1000 points. En mode 1500 pique double, cette application double tous les points des donnes et des annonces ; l’objectif est de 1500 points.", "help_scores_title": "Inscrire les points d’une donne", "help_scores_body": "Saisissez les points d’une équipe, puis validez ou quittez la case. L’autre score vaut 157 moins les points saisis : par exemple, 100 pour Nous donne 57 pour Eux. Les valeurs autorisées sont les entiers de 2 à 155, ou 257 pour un match. Chaque équipe a au moins 2 points dans une donne normale. Les saisies de 0, 1 et de 156 à 256 sont refusées ; 0 est calculé automatiquement pour l’équipe qui subit un match.", "help_order_title": "Remplir les donnes dans l’ordre", "help_order_body": "Seule la première ligne vide est accessible. Les lignes suivantes restent grisées jusqu’à ce que la précédente soit remplie. Les lignes déjà remplies restent modifiables. Pour corriger une donne, modifiez une case. Pour l’effacer, videz une case et validez : cette donne et toutes les suivantes sont effacées pour conserver l’ordre.", "help_match_title": "Compter un match", "help_match_body": "257 donne 0 à l’autre équipe et ajoute un match au compteur. Si une équipe remporte tous les points de la donne, inscrivez 257, pas 157. Le + de « Match » inscrit 257 sur la prochaine ligne libre. Le − retire le dernier match de cette équipe et efface sa donne ainsi que les suivantes. Corriger ou effacer un 257 ajuste le compteur. Les 257 points sont inclus dans les donnes et ne sont pas ajoutés une deuxième fois aux annonces.", "help_ann_title": "Ajouter les annonces", "help_ann_body": "Utilisez + et − dans les annonces de chaque équipe pour compter les annonces de 20, 50, 100, 150 ou 200 points. Leur total s’ajoute aux points des donnes. Les petites cartes neuf et J servent de repères visuels pour les annonces de 150 et 200. Le bouton carré A entre les repères 100 et 20 permet d’ajouter des points d’annonces à cette équipe uniquement, sans complément à 157 pour l’adversaire. Le bouton A ouvre une liste : 3 cartes (20), 4 cartes (50), 5 cartes ou carré (100), quatre neuf (150), quatre valets (200). Ajustez les quantités avec − et +, puis validez avec OK. Annuler ignore les changements. Les annonces de 50 restent représentées par des traits de 50 sur la diagonale, sans être converties en traits de 100. Une annonce de 150 se note avec un trait de 100 en haut et un trait de 50 sur la diagonale. Vous pouvez sélectionner toutes vos annonces avant de valider avec OK, même si leur total dépasse l’objectif : par exemple, ajouter 70 lorsqu’il manque 50. Dès la validation qui donne la victoire, les nouveaux ajouts d’annonces sont bloqués. La flèche de correction permet toujours de corriger la dernière saisie.", "help_finish_title": "Terminer une partie", "help_finish_body": "Les totaux se mettent à jour automatiquement. La première équipe qui atteint ou dépasse 1000 ou 1500 selon le mode gagne. Le gagnant reste enregistré même si des points sont ajoutés ensuite. Il n’y a pas d’égalité. « Nouvelle partie », après confirmation, enregistre la partie et remet les scores à zéro. Une partie contenant des scores ou des annonces est enregistrée même avant l’objectif ; une partie vide ne l’est pas. Les noms et le mode sont conservés.", "help_history_title": "Consulter l’historique", "help_history_body": "« Historique » affiche les parties, leurs dates, les équipes, les scores, le mode, les points d’annonces et le nombre de match. Pour les anciennes parties sans compteur enregistré, « — » apparaît. Le gagnant est la première équipe arrivée à l’objectif. Une partie arrêtée avant l’objectif n’a pas de gagnant. Si le gagnant n’avait pas été enregistré, « Gagnant non enregistré » apparaît. La croix supprime une partie après confirmation ; « Effacer historique » supprime toutes les parties après confirmation. L’icône sous la croix partage le résumé avec scores, annonces et match ; sinon, vous pouvez le copier. Les parties jouées sur l’ardoise sont enregistrées dans le même historique lorsque vous confirmez « Nouvelle partie ». Elles portent la mention « Partie sur ardoise ». Le bouton « Historique » de l’ardoise ouvre cette liste et « Retour au jeu » revient à l’ardoise.", "help_save_title": "Sauvegarde, partage et impression", "help_save_body": "La partie en cours et l’historique sont sauvegardés dans le navigateur de cet appareil, sans synchronisation avec les autres appareils. Effacer les données du navigateur peut supprimer ces sauvegardes. Le partage à côté du titre partage ou copie l’adresse du programme, sans partager les parties enregistrées. « Ardoise » ouvre l’ardoise en plein écran ; « Imprimer historique » imprime les parties affichées.", "help_install_title": "Installer sur le téléphone", "help_install_body": "Ouvrez la page du jeu sur le site avec une connexion Internet, puis installez depuis cette page, pas depuis l’aide. Sur Android, dans Chrome, ouvrez ⋮, puis « Ajouter à l’écran d’accueil » et « Installer », ou directement « Installer l’application » selon la version. Sur iPhone, dans Safari, utilisez Partager (carré avec flèche), puis « Sur l’écran d’accueil » ; activez « Ouvrir comme app web » si proposé et touchez « Ajouter ». Touchez ensuite l’icône Chibre Suisse pour lancer le jeu. Ouvrez-la une première fois avec Internet pour charger les fichiers hors connexion. Les intitulés varient selon la version du téléphone. Après publication sur un site HTTPS, ouvrez le jeu une première fois avec Internet et attendez la fin du chargement. Le jeu, l’aide, les cinq langues et l’historique restent ensuite utilisables sans connexion sur ce même appareil. Les liens vers les sites externes et l’envoi des partages nécessitent une connexion.", "help_language_title": "Choisir la langue", "help_language_body": "Le drapeau suisse ouvre le choix Français, Deutsch, Italiano, Rumantsch ou English. La langue est mémorisée pour ce navigateur et s’applique au jeu, à l’aide, aux messages et aux résumés partagés. Les noms des participants ne sont pas traduits. Le romanche utilisé est le rumantsch grischun.", "official": "Instructions officielles :", "language_question": "Voulez-vous changer la langue en {language} ?", "cards_20": "3 cartes", "cards_50": "4 cartes", "cards_100": "5 cartes", "four_kind": "ou Carré", "slate_open": "Ouvrir l’ardoise des points", "slate_title": "Ardoise", "slate_close": "Fermer l’ardoise", "slate_legend": "100 : traits en haut · 50 : diagonale · 20 : traits en bas · reste en chiffres. L’autre équipe est tournée vers son côté de table.", "slate_readout": "{total} points : {hundreds} traits de 100, {fifties} de 50, {twenties} de 20 et {remainder} points restants.", "slate_add": "Ajouter {value} points pour {team}", "manual_title": "Ajouter des points pour {team}", "manual_value": "Points à ajouter", "cancel": "Annuler", "add_points": "Ajouter", "manual_invalid": "Saisissez un nombre entier entre 2 et 155, ou 257 pour un match.", "ann_manual_title": "Annonces pour {team}", "ann_value": "Points d’annonces à ajouter", "ann_invalid": "Saisissez un nombre entier de points supérieur à zéro.", "slate_edit": "Modifier la dernière saisie de {team}", "update": "Modifier", "slate_mode_button": "Ardoise", "four_nines": "Quatre neuf", "four_jacks": "Quatre valets", "slate_game": "Partie sur ardoise", "ann_symbol": "A", "edit_name": "Modifier les noms", "add_round": "Ajouter à {team} — donne {number} ?", "edit_round": "Modifier la donne {number} — {team}", "double_toggle": "♠ ♠", "help_slate_use_title": "Utiliser l’ardoise", "help_slate_use_body": "Ouvrez « Ardoise » pour voir les deux équipes en plein écran. Touchez un nom pour le modifier. Touchez la zone noire entre les lignes du Z pour entrer les points de la donne : la fenêtre affiche l’équipe choisie et le numéro de donne. Le numéro avance uniquement après validation, pas après Annuler ni après une annonce. Saisissez 2 à 155, ou 257 pour un match. L’adversaire reçoit automatiquement 157 moins les points saisis ; pour 257, il reçoit 0. Les lignes du Z ne sont pas cliquables. Fermez l’ardoise avec la croix en haut à droite.", "help_slate_ann_title": "Annonces sur l’ardoise", "help_slate_ann_body": "Le bouton A ouvre les annonces : 20 pour 3 cartes, 50 pour 4 cartes, 100 pour 5 cartes ou un carré, 150 pour quatre neuf et 200 pour quatre valets. Les cartes 9 et J sont illustrées avec leurs couleurs. Choisissez les quantités avec − et +, puis appuyez sur OK pour appliquer le total une seule fois. Annuler ne change rien. Les annonces vont uniquement à l’équipe choisie : aucun complément à 157 n’est attribué à l’adversaire. Le bouton devient W en allemand et M en anglais. Si vous avez 950 points, vous pouvez encore valider 70 points d’annonces : vous arrivez à 1020 et gagnez. Après la victoire, aucun nouvel ajout d’annonces n’est permis.", "help_slate_read_title": "Lire et corriger l’ardoise", "help_slate_read_body": "Les traits du haut valent 100, ceux de la diagonale 50 et ceux du bas 20 ; le reste est écrit en chiffres. Les traits sont regroupés par cinq : quatre barres et une diagonale qui les traverse. Les annonces de 50 restent dans les 50 et les saisies de 20 restent dans les 20, même si leur somme atteint 100. Une annonce de 150 donne un trait de 100 et un trait de 50. La flèche blanche ↶ sous les 20 rouvre la dernière saisie de l’équipe avec le nombre prérempli ; pour les points, le numéro de donne est indiqué. Modifier remplace la saisie, recalcule les points adverses si nécessaire et ne crée pas une nouvelle donne. Les anciennes saisies dont le détail n’avait pas été conservé peuvent ne pas être rééditables.", "help_slate_double_title": "Pique double et fin de partie", "help_slate_double_body": "Le bouton central « Pique double ON/OFF » est commun aux deux équipes. OFF utilise l’objectif de 1000 points ; ON utilise 1500 et double les points et les annonces. Saisissez toujours les points simples : 100 contre 57 devient 200 contre 114, un match de 257 vaut 514 et une annonce de 50 vaut 100. Le changement de mode recalcule aussi les totaux déjà saisis. La première équipe qui atteint ou dépasse l’objectif gagne ; le message apparaît au-dessus de l’ardoise. Nouvelle partie demande confirmation, enregistre la partie dans l’historique et remet les points à zéro. Historique ouvre les parties enregistrées, avec la mention Partie sur ardoise. Retour au jeu ramène à l’ardoise.", "round_numbers": "Numéro de donne", "close_victory": "Fermer le panneau de victoire"}, "de": {"choose": "Sprache wählen", "subtitle": "Punkteblatt", "print": "Drucken", "new": "Neue Partie", "history": "Verlauf", "history_title": "Partienverlauf", "back": "Zurück zum Spiel", "clear": "Verlauf löschen", "print_history": "🖨️ Verlauf drucken", "normal": "1000 • normal", "double": "1500 • ♠ ♠", "team_a": "Team Wir", "team_b": "Team Sie", "us": "Wir", "them": "Sie", "names": "Namen eingeben", "ann": "Weis", "ann_title": "Weis {name}", "round_points": "Rundenpunkte", "round": "Runde", "round_label": "Runde {number} {team}", "match": "Match", "help": "wie funktioniert’s?", "help_title": "Wie funktioniert’s?", "share": "Teilen", "delete_question": "Diese Partie löschen?", "yes": "Ja", "no": "Nein", "validation": "Geben Sie eine ganze Zahl von 2 bis 155 ein oder 257 für einen Match.", "full": "Alle 12 Runden sind bereits ausgefüllt.", "win": "🏆 {name} hat gewonnen! {total} Punkte", "empty": "Keine Partie gespeichert.", "winner": "Gewinner", "unfinished": "Partie vor Erreichen des Ziels beendet", "unknown": "Gewinner nicht gespeichert", "part": "Partie", "mode": "Modus", "points": "Punkte", "pts": "Pkt.", "delete_part": "Diese Partie löschen", "delete_number": "Partie {number} löschen", "share_part": "Diese Partie teilen", "share_number": "Partie {number} teilen", "clear_question": "Den gesamten Partienverlauf endgültig löschen?", "reset_question": "Diese Partie beenden und eine neue beginnen?", "summary_copied": "Zusammenfassung der Partie kopiert!", "copy_summary": "Kopieren Sie die Zusammenfassung der Partie:", "link_copied": "Link kopiert!", "share_unavailable": "Teilen ist auf diesem Gerät nicht verfügbar.", "app_description": "Installierbares Chibre-Punkteblatt für das Smartphone.", "share_description": "Chibre-Punkteblatt", "card_title": "{suit}-{rank}", "nine": "Neun", "jack": "Bube", "spade": "Pik (am stärksten)", "heart": "Herz", "diamond": "Karo", "club": "Kreuz (am schwächsten)", "increase": "{value} für {team} hinzufügen", "decrease": "{value} für {team} abziehen", "info": "Erlaubte Eingaben: <b>2 bis 155 oder 257 für einen Match</b>. Bei 257 erhält das andere Team <b>0 Punkte</b> und ein Match wird automatisch gezählt. Sonst: <b>157 − eingegebene Punkte</b>. Im Modus 1500 wird die Gesamtsumme einmal verdoppelt.", "help_start_title": "Eine Partie beginnen", "help_start_body": "Tragen Sie die Namen bei «Wir» und «Sie» ein und wählen Sie den Modus. Das Punkteblatt zeigt zunächst 8 Runden. Sind alle sichtbaren Zeilen ausgefüllt und hat noch kein Team gewonnen, erscheint jeweils eine weitere Zeile, bis höchstens 12 Runden. Im normalen Modus 1000 zählen Runden- und Weispunkte einfach; das Ziel sind 1000 Punkte. Im Modus 1500 Pik doppelt verdoppelt diese App sämtliche Runden- und Weispunkte; das Ziel sind 1500 Punkte.", "help_scores_title": "Rundenpunkte eintragen", "help_scores_body": "Geben Sie die Punkte eines Teams ein und bestätigen Sie die Eingabe oder verlassen Sie das Feld. Das andere Team erhält 157 minus die eingegebenen Punkte: 100 für Wir ergibt beispielsweise 57 für Sie. Erlaubt sind ganze Zahlen von 2 bis 155 oder 257 für einen Match. In einer normalen Runde erhält jedes Team mindestens 2 Punkte. Eingaben von 0, 1 und 156 bis 256 werden abgelehnt; 0 wird für das Team, das einen Match verliert, automatisch berechnet.", "help_order_title": "Runden der Reihe nach ausfüllen", "help_order_body": "Nur die erste leere Zeile ist freigegeben. Die folgenden Zeilen bleiben grau, bis die vorherige ausgefüllt ist. Bereits ausgefüllte Zeilen können weiterhin geändert werden. Zum Korrigieren ändern Sie ein Feld. Zum Löschen leeren Sie ein Feld und bestätigen: Diese Runde und alle folgenden werden gelöscht, damit die Reihenfolge erhalten bleibt.", "help_match_title": "Einen Match zählen", "help_match_body": "257 ergibt 0 für das andere Team und erhöht den Match-Zähler. Gewinnt ein Team alle Punkte einer Runde, geben Sie 257 ein, nicht 157. Das + bei «Match» trägt 257 in die nächste freie Zeile ein. Das − entfernt den letzten Match dieses Teams und löscht dessen Runde sowie alle folgenden. Beim Ändern oder Löschen von 257 wird der Zähler angepasst. Die 257 Punkte sind bereits in den Runden enthalten und werden nicht nochmals als Weis addiert.", "help_ann_title": "Weis hinzufügen", "help_ann_body": "Zählen Sie mit + und − bei jedem Team die Weise von 20, 50, 100, 150 oder 200 Punkten. Die Summe wird zu den Rundenpunkten addiert. Die kleinen Karten 9 und J dienen als visuelle Hinweise für die Weise von 150 und 200. Mit der quadratischen Taste W zwischen 100 und 20 können Sie nur diesem Team Weispunkte hinzufügen, ohne Ergänzung auf 157 für das andere Team. Die Taste W öffnet die Auswahl: 3 Karten (20), 4 Karten (50), 5 Karten oder Vierling (100), vier Neuner (150), vier Buben (200). Ändern Sie die Anzahl mit − und + und bestätigen Sie mit OK. Abbrechen verwirft die Änderungen. Fünfziger-Weise bleiben als 50er-Striche auf der Diagonale stehen und werden nicht in 100er-Striche umgewandelt. Ein Weis von 150 wird als ein 100er-Strich oben und ein 50er-Strich auf der Diagonale dargestellt. Sie können alle Weise vor dem Bestätigen mit OK auswählen, auch wenn die Summe das Ziel überschreitet, etwa 70, wenn noch 50 fehlen. Sobald die Bestätigung den Sieg auslöst, sind neue Weise gesperrt. Der Korrekturpfeil bleibt für die letzte Eingabe verfügbar.", "help_finish_title": "Eine Partie beenden", "help_finish_body": "Die Summen werden automatisch aktualisiert. Das erste Team, das je nach Modus 1000 oder 1500 erreicht oder überschreitet, gewinnt. Der Gewinner bleibt gespeichert, auch wenn später weitere Punkte eingetragen werden. Es gibt kein Unentschieden. «Neue Partie» speichert nach Bestätigung die Partie und setzt die Punkte zurück. Partien mit Punkten oder Weis werden auch vor Erreichen des Ziels gespeichert; leere Partien nicht. Namen und Modus bleiben erhalten.", "help_history_title": "Den Verlauf ansehen", "help_history_body": "«Verlauf» zeigt Partien, Datum, Teams, Punkte, Modus, Weispunkte und Match-Zähler. Bei älteren Partien ohne gespeicherten Zähler erscheint «—». Gewinner ist das erste Team, das das Ziel erreicht hat. Vorzeitig beendete Partien haben keinen Gewinner. Wurde der Gewinner nicht gespeichert, erscheint «Gewinner nicht gespeichert». Das Kreuz löscht nach Bestätigung eine Partie; «Verlauf löschen» löscht nach Bestätigung alle Partien. Das Symbol unter dem Kreuz teilt die Zusammenfassung mit Punkten, Weis und Match; andernfalls können Sie sie kopieren. Auf der Tafel gespielte Partien werden beim Bestätigen von «Neue Partie» im selben Verlauf gespeichert und als «Partie auf der Tafel» gekennzeichnet. «Verlauf» auf der Tafel öffnet die Liste; «Zurück zum Spiel» kehrt zur Tafel zurück.", "help_save_title": "Speichern, Teilen und Drucken", "help_save_body": "Die laufende Partie und der Verlauf werden im Browser dieses Geräts gespeichert und nicht mit anderen Geräten synchronisiert. Das Löschen der Browserdaten kann diese gespeicherten Daten entfernen. Das Teilen-Symbol neben dem Titel teilt oder kopiert die Adresse der App, nicht die gespeicherten Partien. «Tafel» öffnet die Tafel bildschirmfüllend; «Verlauf drucken» druckt die angezeigten Partien.", "help_install_title": "Auf dem Smartphone installieren", "help_install_body": "Öffnen Sie die Spielseite im Internet und installieren Sie von dort, nicht von dieser Hilfeseite. Unter Android öffnen Sie in Chrome ⋮, dann «Zum Startbildschirm hinzufügen» und «Installieren» oder je nach Version direkt «App installieren». Auf dem iPhone wählen Sie in Safari Teilen (Quadrat mit Pfeil), dann «Zum Home-Bildschirm»; aktivieren Sie «Als Web-App öffnen», falls angeboten, und tippen Sie auf «Hinzufügen». Tippen Sie danach auf das Symbol Chibre Suisse, um das Spiel zu starten. Öffnen Sie es zunächst mit Internetverbindung, damit die Dateien für die Offline-Nutzung geladen werden. Die Menütexte hängen von der Telefonversion ab. Öffnen Sie nach der Veröffentlichung auf einer HTTPS-Website das Spiel einmal mit Internetverbindung und warten Sie, bis es vollständig geladen ist. Spiel, Hilfe, fünf Sprachen und Verlauf können danach auf demselben Gerät offline genutzt werden. Externe Links und das Versenden geteilter Inhalte benötigen eine Verbindung.", "help_language_title": "Sprache wählen", "help_language_body": "Die Schweizer Flagge öffnet die Auswahl Français, Deutsch, Italiano, Rumantsch oder English. Die Sprache wird in diesem Browser gespeichert und für das Spiel, die Hilfe, Meldungen und geteilte Zusammenfassungen verwendet. Die Namen der Teilnehmenden werden nicht übersetzt. Die romanische Fassung verwendet Rumantsch Grischun.", "official": "Offizielle Anleitungen:", "language_question": "Möchten Sie die Sprache zu {language} ändern?", "cards_20": "3 Karten", "cards_50": "4 Karten", "cards_100": "5 Karten", "four_kind": "oder Vierling", "slate_open": "Punktetafel öffnen", "slate_title": "Tafel", "slate_close": "Tafel schliessen", "slate_legend": "100: Striche oben · 50: Diagonale · 20: Striche unten · Rest als Zahl. Das andere Team ist zur gegenüberliegenden Tischseite ausgerichtet.", "slate_readout": "{total} Punkte: {hundreds} Hunderter, {fifties} Fünfziger, {twenties} Zwanziger und {remainder} Restpunkte.", "slate_add": "{value} Punkte für {team} hinzufügen", "manual_title": "Punkte für {team} hinzufügen", "manual_value": "Hinzuzufügende Punkte", "cancel": "Abbrechen", "add_points": "Hinzufügen", "manual_invalid": "Geben Sie eine ganze Zahl von 2 bis 155 ein oder 257 für einen Match.", "ann_manual_title": "Weis für {team}", "ann_value": "Hinzuzufügende Weispunkte", "ann_invalid": "Geben Sie eine ganze Punktzahl grösser als null ein.", "slate_edit": "Letzte Eingabe für {team} bearbeiten", "update": "Ändern", "slate_mode_button": "Tafel", "four_nines": "Vier Neuner", "four_jacks": "Vier Buben", "slate_game": "Partie auf der Tafel", "ann_symbol": "W", "edit_name": "Namen ändern", "add_round": "Für {team} hinzufügen — Runde {number}?", "edit_round": "Runde {number} ändern — {team}", "double_toggle": "♠ ♠", "help_slate_use_title": "Die Tafel verwenden", "help_slate_use_body": "Öffnen Sie die Tafel, um beide Teams bildschirmfüllend zu sehen. Tippen Sie auf einen Namen, um ihn zu ändern. Tippen Sie auf die schwarze Fläche zwischen den Z-Linien, um die Rundenpunkte einzugeben. Das Fenster zeigt das Team und die Rundennummer. Die Nummer steigt erst nach Bestätigung, nicht nach Abbrechen oder einem Weis. Geben Sie 2 bis 155 oder 257 für einen Match ein. Das andere Team erhält automatisch 157 minus die Eingabe; bei 257 erhält es 0. Die Z-Linien sind nicht anklickbar. Schliessen Sie die Tafel mit dem Kreuz oben rechts.", "help_slate_ann_title": "Weis auf der Tafel", "help_slate_ann_body": "Die Taste W öffnet die Weise: 20 für 3 Karten, 50 für 4 Karten, 100 für 5 Karten oder einen Vierling, 150 für vier Neuner und 200 für vier Buben. Neuner und Buben sind farbig abgebildet. Wählen Sie die Anzahl mit − und + und bestätigen Sie mit OK; die Summe wird einmal hinzugefügt. Abbrechen ändert nichts. Nur das ausgewählte Team erhält Weispunkte, ohne Ergänzung auf 157 für den Gegner. Die Taste heisst A auf Französisch, Italienisch und Romanisch und M auf Englisch. Bei 950 Punkten können Sie 70 Weispunkte bestätigen: Mit 1020 gewinnen Sie. Nach dem Sieg sind neue Weise gesperrt.", "help_slate_read_title": "Die Tafel lesen und korrigieren", "help_slate_read_body": "Obere Striche zählen 100, diagonale 50 und untere 20; der Rest steht als Zahl. Je fünf Striche bestehen aus vier Strichen und einem diagonalen Querstrich. Fünfziger-Weise bleiben bei den 50ern und Eingaben von 20 bei den 20ern, auch wenn ihre Summe 100 ergibt. Ein Weis von 150 ergibt einen 100er und einen 50er. Der weisse Pfeil ↶ unter den 20ern öffnet die letzte Eingabe des Teams vorausgefüllt; bei Punkten wird die Rundennummer angezeigt. Ändern ersetzt die Eingabe, korrigiert gegebenenfalls die Gegnerpunkte und erstellt keine neue Runde. Ältere Eingaben ohne gespeicherte Details sind möglicherweise nicht bearbeitbar.", "help_slate_double_title": "Pik doppelt und Spielende", "help_slate_double_body": "Die mittlere Taste «Pik doppelt ON/OFF» gilt für beide Teams. OFF verwendet das Ziel 1000; ON verwendet 1500 und verdoppelt Punkte und Weis. Geben Sie immer die einfachen Punkte ein: 100 gegen 57 wird 200 gegen 114, ein Match von 257 zählt 514 und ein Weis von 50 zählt 100. Ein Moduswechsel berechnet auch bereits eingegebene Summen neu. Das erste Team, das das Ziel erreicht oder überschreitet, gewinnt; die Meldung erscheint über der Tafel. Neue Partie fragt nach Bestätigung, speichert die Partie im Verlauf und setzt die Punkte zurück. Verlauf zeigt gespeicherte Partien mit der Kennzeichnung Partie auf der Tafel. Zurück zum Spiel kehrt zur Tafel zurück.", "round_numbers": "Rundennummer", "close_victory": "Gewinnmeldung schliessen"}, "it": {"choose": "Scegli la lingua", "subtitle": "Segnapunti", "print": "Stampa", "new": "Nuova partita", "history": "Cronologia", "history_title": "Cronologia delle partite", "back": "Torna al gioco", "clear": "Cancella cronologia", "print_history": "🖨️ Stampa cronologia", "normal": "1000 • normale", "double": "1500 • ♠ ♠", "team_a": "Squadra Noi", "team_b": "Squadra Loro", "us": "Noi", "them": "Loro", "names": "Inserite i vostri nomi", "ann": "Annunci", "ann_title": "Annunci {name}", "round_points": "Punti delle mani", "round": "Mano", "round_label": "Mano {number} {team}", "match": "Match", "help": "come funziona?", "help_title": "Come funziona?", "share": "Condividi", "delete_question": "Eliminare questa partita?", "yes": "Sì", "no": "No", "validation": "Inserite un numero intero da 2 a 155, oppure 257 per un match.", "full": "Le 12 mani sono già compilate.", "win": "🏆 {name} ha vinto! {total} punti", "empty": "Nessuna partita salvata.", "winner": "Vincitore", "unfinished": "Partita terminata prima dell’obiettivo", "unknown": "Vincitore non registrato", "part": "Partita", "mode": "Modalità", "points": "punti", "pts": "pt", "delete_part": "Elimina questa partita", "delete_number": "Elimina la partita {number}", "share_part": "Condividi questa partita", "share_number": "Condividi la partita {number}", "clear_question": "Cancellare definitivamente tutta la cronologia delle partite?", "reset_question": "Terminare questa partita e iniziarne una nuova?", "summary_copied": "Riepilogo della partita copiato!", "copy_summary": "Copiate il riepilogo della partita:", "link_copied": "Link copiato!", "share_unavailable": "La condivisione non è disponibile su questo dispositivo.", "app_description": "Segnapunti Chibre installabile sul telefono.", "share_description": "Segnapunti Chibre", "card_title": "{rank} di {suit}", "nine": "Nove", "jack": "Fante", "spade": "Picche (il più forte)", "heart": "Cuori", "diamond": "Quadri", "club": "Fiori (il più debole)", "increase": "Aggiungi {value} per {team}", "decrease": "Togli {value} per {team}", "info": "Valori ammessi: <b>da 2 a 155, oppure 257 per un match</b>. Inserendo 257, l’altra squadra riceve <b>0 punti</b> e viene contato automaticamente un match. Altrimenti: <b>157 − punti inseriti</b>. In modalità 1500 il totale viene raddoppiato una sola volta.", "help_start_title": "Iniziare una partita", "help_start_body": "Inserite i nomi dei giocatori in «Noi» e «Loro», poi scegliete la modalità. Il foglio mostra inizialmente 8 mani. Quando tutte le righe visibili sono compilate e nessuna squadra ha vinto, appare una nuova riga, fino a un massimo di 12 mani. Nella modalità 1000 normale, i punti delle mani e degli annunci contano una volta; l’obiettivo è di 1000 punti. Nella modalità 1500 picche doppie, questa applicazione raddoppia tutti i punti delle mani e degli annunci; l’obiettivo è di 1500 punti.", "help_scores_title": "Inserire i punti di una mano", "help_scores_body": "Inserite i punti di una squadra e confermate oppure uscite dalla casella. L’altro punteggio è 157 meno i punti inseriti: per esempio, 100 per Noi dà 57 per Loro. Sono ammessi i numeri interi da 2 a 155, oppure 257 per un match. Ogni squadra riceve almeno 2 punti in una mano normale. I valori 0, 1 e da 156 a 256 sono rifiutati; lo 0 viene calcolato automaticamente per la squadra che subisce un match.", "help_order_title": "Compilare le mani in ordine", "help_order_body": "Solo la prima riga vuota è attiva. Le righe successive restano grigie finché la precedente non è compilata. Le righe già compilate restano modificabili. Per correggere una mano, modificate una casella. Per cancellarla, svuotate una casella e confermate: questa mano e tutte le successive vengono cancellate per mantenere l’ordine.", "help_match_title": "Contare un match", "help_match_body": "257 assegna 0 all’altra squadra e aggiunge un match al contatore. Se una squadra conquista tutti i punti della mano, inserite 257, non 157. Il + di «Match» inserisce 257 nella prossima riga libera. Il − rimuove l’ultimo match di quella squadra e cancella la sua mano e quelle successive. Correggere o cancellare un 257 aggiorna il contatore. I 257 punti sono inclusi nelle mani e non vengono aggiunti una seconda volta agli annunci.", "help_ann_title": "Aggiungere gli annunci", "help_ann_body": "Usate + e − negli annunci di ciascuna squadra per contare gli annunci da 20, 50, 100, 150 o 200 punti. Il loro totale si aggiunge ai punti delle mani. Le piccole carte 9 e J sono riferimenti visivi per gli annunci da 150 e 200. Il pulsante quadrato A tra 100 e 20 aggiunge punti degli annunci solo a questa squadra, senza assegnare all’avversario la differenza rispetto a 157. Il pulsante A apre la lista: 3 carte (20), 4 carte (50), 5 carte o poker (100), quattro nove (150), quattro fanti (200). Regolate le quantità con − e + e confermate con OK. Annulla ignora le modifiche. Gli annunci da 50 restano come tratti da 50 sulla diagonale, senza essere convertiti in tratti da 100. Un annuncio da 150 viene rappresentato con un tratto da 100 in alto e uno da 50 sulla diagonale. Potete selezionare tutti gli annunci prima di confermare con OK, anche se il totale supera l’obiettivo: per esempio 70 quando mancano 50. Dopo la conferma che determina la vittoria, non è possibile aggiungere nuovi annunci. La freccia permette ancora di correggere l’ultimo inserimento.", "help_finish_title": "Terminare una partita", "help_finish_body": "I totali si aggiornano automaticamente. Vince la prima squadra che raggiunge o supera 1000 o 1500 punti, secondo la modalità. Il vincitore resta registrato anche se vengono aggiunti altri punti. Non c’è pareggio. «Nuova partita», dopo la conferma, salva la partita e azzera i punteggi. Una partita con punti o annunci viene salvata anche prima dell’obiettivo; una partita vuota no. Nomi e modalità vengono conservati.", "help_history_title": "Consultare la cronologia", "help_history_body": "«Cronologia» mostra le partite, le date, le squadre, i punteggi, la modalità, i punti degli annunci e il numero di match. Per le vecchie partite senza contatore salvato compare «—». Vince la prima squadra che ha raggiunto l’obiettivo. Le partite interrotte prima dell’obiettivo non hanno vincitore. Se il vincitore non era stato salvato, compare «Vincitore non registrato». La croce elimina una partita dopo la conferma; «Cancella cronologia» elimina tutte le partite dopo la conferma. L’icona sotto la croce condivide il riepilogo con punti, annunci e match; altrimenti potete copiarlo. Le partite giocate sulla lavagna vengono salvate nella stessa cronologia quando confermate «Nuova partita», con la dicitura «Partita sulla lavagna». «Cronologia» sulla lavagna apre la lista e «Torna al gioco» torna alla lavagna.", "help_save_title": "Salvataggio, condivisione e stampa", "help_save_body": "La partita in corso e la cronologia vengono salvate nel browser di questo dispositivo, senza sincronizzazione con altri dispositivi. Cancellare i dati del browser può eliminare questi salvataggi. Il pulsante di condivisione accanto al titolo condivide o copia l’indirizzo del programma, senza condividere le partite salvate. «Lavagna» apre la lavagna a schermo intero; «Stampa cronologia» stampa le partite visualizzate.", "help_install_title": "Installare sul telefono", "help_install_body": "Aprite la pagina del gioco sul sito con una connessione Internet e installate da lì, non da questa guida. Su Android, in Chrome, aprite ⋮, poi «Aggiungi a schermata Home» e «Installa», oppure direttamente «Installa app», secondo la versione. Su iPhone, in Safari, usate Condividi (quadrato con freccia), poi «Aggiungi alla schermata Home»; attivate «Apri come app web» se disponibile e toccate «Aggiungi». Toccate quindi l’icona Chibre Suisse per avviare il gioco. Apritela una prima volta con Internet per caricare i file necessari all’uso offline. Le voci dei menu possono variare secondo la versione del telefono. Dopo la pubblicazione su un sito HTTPS, aprite il gioco una prima volta con Internet e attendete il caricamento completo. Il gioco, la guida, le cinque lingue e la cronologia restano poi utilizzabili offline sullo stesso dispositivo. I link esterni e l’invio dei contenuti condivisi richiedono una connessione.", "help_language_title": "Scegliere la lingua", "help_language_body": "La bandiera svizzera apre la scelta Français, Deutsch, Italiano, Rumantsch o English. La lingua viene memorizzata in questo browser e si applica al gioco, alla guida, ai messaggi e ai riepiloghi condivisi. I nomi dei partecipanti non vengono tradotti. La versione romancia usa il rumantsch grischun.", "official": "Istruzioni ufficiali:", "language_question": "Vuoi cambiare la lingua in {language}?", "cards_20": "3 carte", "cards_50": "4 carte", "cards_100": "5 carte", "four_kind": "oppure poker", "slate_open": "Apri la lavagna dei punti", "slate_title": "Lavagna", "slate_close": "Chiudi la lavagna", "slate_legend": "100: tratti in alto · 50: diagonale · 20: tratti in basso · resto in cifre. L’altra squadra è rivolta verso il proprio lato del tavolo.", "slate_readout": "{total} punti: {hundreds} tratti da 100, {fifties} da 50, {twenties} da 20 e {remainder} punti rimanenti.", "slate_add": "Aggiungi {value} punti per {team}", "manual_title": "Aggiungi punti per {team}", "manual_value": "Punti da aggiungere", "cancel": "Annulla", "add_points": "Aggiungi", "manual_invalid": "Inserite un numero intero da 2 a 155, oppure 257 per un match.", "ann_manual_title": "Annunci per {team}", "ann_value": "Punti degli annunci da aggiungere", "ann_invalid": "Inserite un numero intero di punti maggiore di zero.", "slate_edit": "Modifica l’ultimo inserimento per {team}", "update": "Modifica", "slate_mode_button": "Lavagna", "four_nines": "Quattro nove", "four_jacks": "Quattro fanti", "slate_game": "Partita sulla lavagna", "ann_symbol": "A", "edit_name": "Modifica i nomi", "add_round": "Aggiungere a {team} — mano {number}?", "edit_round": "Modifica la mano {number} — {team}", "double_toggle": "♠ ♠", "help_slate_use_title": "Usare la lavagna", "help_slate_use_body": "Aprite la lavagna per vedere entrambe le squadre a schermo intero. Toccate un nome per modificarlo. Toccate la zona nera tra le linee della Z per inserire i punti: la finestra mostra squadra e numero della mano. Il numero avanza solo dopo la conferma, non dopo Annulla o un annuncio. Inserite da 2 a 155, oppure 257 per un match. L’avversario riceve automaticamente 157 meno i punti inseriti; con 257 riceve 0. Le linee della Z non sono cliccabili. Chiudete con la croce in alto a destra.", "help_slate_ann_title": "Annunci sulla lavagna", "help_slate_ann_body": "Il pulsante A apre gli annunci: 20 per 3 carte, 50 per 4 carte, 100 per 5 carte o un poker, 150 per quattro nove e 200 per quattro fanti. Le carte 9 e J sono illustrate a colori. Scegliete le quantità con − e + e confermate con OK: il totale viene aggiunto una sola volta. Annulla non cambia nulla. Gli annunci vanno solo alla squadra scelta, senza complemento a 157 per l’avversario. Il pulsante diventa W in tedesco e M in inglese. A 950 punti potete confermare 70 punti di annunci: arrivate a 1020 e vincete. Dopo la vittoria non si possono aggiungere nuovi annunci.", "help_slate_read_title": "Leggere e correggere la lavagna", "help_slate_read_body": "I tratti in alto valgono 100, quelli sulla diagonale 50 e quelli in basso 20; il resto è scritto in cifre. Ogni gruppo di cinque contiene quattro tratti e una diagonale che li attraversa. Gli annunci da 50 restano nei 50 e i punteggi da 20 nei 20, anche se la somma arriva a 100. Un annuncio da 150 dà un tratto da 100 e uno da 50. La freccia bianca ↶ sotto i 20 riapre l’ultimo inserimento della squadra con il numero precompilato; per i punti è indicato il numero della mano. Modifica sostituisce il valore, ricalcola se necessario i punti avversari e non crea una nuova mano. I vecchi inserimenti senza dettagli salvati potrebbero non essere modificabili.", "help_slate_double_title": "Picche doppie e fine della partita", "help_slate_double_body": "Il pulsante centrale «Picche doppie ON/OFF» vale per entrambe le squadre. OFF usa l’obiettivo di 1000 punti; ON usa 1500 e raddoppia punti e annunci. Inserite sempre i punti semplici: 100 contro 57 diventa 200 contro 114, un match da 257 vale 514 e un annuncio da 50 vale 100. Cambiare modalità ricalcola anche i totali già inseriti. Vince la prima squadra che raggiunge o supera l’obiettivo; il messaggio appare sopra la lavagna. Nuova partita chiede conferma, salva la partita nella cronologia e azzera i punti. Cronologia mostra le partite salvate con la dicitura Partita sulla lavagna. Torna al gioco torna alla lavagna.", "round_numbers": "Numero della mano", "close_victory": "Chiudi il pannello della vittoria"}, "rm": {"choose": "Tscherner la lingua", "subtitle": "Fegl da puncts", "print": "Stampar", "new": "Nova partida", "history": "Cronologia", "history_title": "Cronologia da las partidas", "back": "Enavos al gieu", "clear": "Stizzar la cronologia", "print_history": "🖨️ Stampar la cronologia", "normal": "1000 • normal", "double": "1500 • ♠ ♠", "team_a": "Equipa Nus", "team_b": "Equipa Els", "us": "Nus", "them": "Els", "names": "Endatai voss nums", "ann": "Annunzias", "ann_title": "Annunzias {name}", "round_points": "Puncts da las rundas", "round": "Runda", "round_label": "Runda {number} {team}", "match": "Match", "help": "co funcziuna quai?", "help_title": "Co funcziuna quai?", "share": "Cundivider", "delete_question": "Stizzar questa partida?", "yes": "Gea", "no": "Na", "validation": "Endatai in dumber entir da 2 fin 155 u 257 per in match.", "full": "Las 12 rundas èn gia emplenidas.", "win": "🏆 {name} ha gudagnà! {total} puncts", "empty": "Naginas partidas memorisadas.", "winner": "Victur", "unfinished": "Partida terminada avant la finamira", "unknown": "Victur betg memorisà", "part": "Partida", "mode": "Modus", "points": "puncts", "pts": "pcts", "delete_part": "Stizzar questa partida", "delete_number": "Stizzar la partida {number}", "share_part": "Cundivider questa partida", "share_number": "Cundivider la partida {number}", "clear_question": "Stizzar definitivamain l’entira cronologia da las partidas?", "reset_question": "Terminar questa partida e cumenzar ina nova partida?", "summary_copied": "Resumaziun da la partida copiada!", "copy_summary": "Copiai la resumaziun da la partida:", "link_copied": "Colliaziun copiada!", "share_unavailable": "Cundivider n’è betg pussaivel sin quest apparat.", "app_description": "Fegl da puncts Chibre installabel sin il telefon.", "share_description": "Fegl da puncts Chibre", "card_title": "{rank} da {suit}", "nine": "Nov", "jack": "Pur", "spade": "Palas (il pli ferm)", "heart": "Cors", "diamond": "Pizs", "club": "Cruschs (il pli flaivel)", "increase": "Agiuntar {value} per {team}", "decrease": "Deductar {value} per {team}", "info": "Endataziuns permessas: <b>2 fin 155 u 257 per in match</b>. Cun 257 survegn l’autra equipa <b>0 puncts</b> ed in match vegn dumbrà automaticamain. Uschiglio: <b>157 − puncts endatads</b>. En il modus 1500 vegn il total dublegià ina suletta giada.", "help_start_title": "Cumenzar ina partida", "help_start_body": "Endatai ils nums da las persunas che giogan tar «Nus» ed «Els» e tschernì il modus. Il fegl mussa 8 rundas a l’entschatta. Sche tut las lingias visiblas èn emplenidas e nagina equipa ha gudagnà, cumpara ina nova lingia, fin maximalmain 12 rundas. En il modus 1000 normal vegnan ils puncts da las rundas e da las annunzias dumbrads ina giada; la finamira è 1000 puncts. En il modus 1500 palas dubel dublegia questa applicaziun tut ils puncts da las rundas e da las annunzias; la finamira è 1500 puncts.", "help_scores_title": "Endatar ils puncts d’ina runda", "help_scores_body": "Endatai ils puncts d’ina equipa e confermai u bandunai il champ. L’autra equipa survegn 157 minus ils puncts endatads: per exempel, 100 per Nus dat 57 per Els. Permess èn dumbers entirs da 2 fin 155 u 257 per in match. En ina runda normala survegn mintga equipa almain 2 puncts. Endataziuns da 0, 1 e da 156 fin 256 vegnan refusadas; 0 vegn calculà automaticamain per l’equipa che perda in match.", "help_order_title": "Emplenir las rundas en successiun", "help_order_body": "Sulettamain l’emprima lingia vida è accessibla. Las lingias suandantas restan grischas fin che la precedenta è emplenida. Las lingias gia emplenidas pon vinavant vegnir midadas. Per curreger ina runda, midai in champ. Per stizzar ella, laschai in champ vid e confermai: questa runda e tut las suandantas vegnan stizzadas per mantegnair la successiun.", "help_match_title": "Dumbrar in match", "help_match_body": "257 dat 0 a l’autra equipa ed agiunta in match al dumbrader. Sche in’equipa gudogna tut ils puncts d’ina runda, endatai 257 e betg 157. Il + tar «Match» endatescha 257 en la proxima lingia libra. Il − allontanescha il davos match da questa equipa e stizza sia runda e las suandantas. Curreger u stizzar in 257 adatta il dumbrader. Ils 257 puncts èn gia inclus en las rundas e na vegnan betg agiuntads ina segunda giada a las annunzias.", "help_ann_title": "Agiuntar las annunzias", "help_ann_body": "Duvrai + e − tar las annunzias da mintga equipa per dumbrar las annunzias da 20, 50, 100, 150 u 200 puncts. Lur total vegn agiuntà als puncts da las rundas. Las pitschnas chartas 9 e J servan sco indizis visuals per las annunzias da 150 e 200. Il buttun quadrat A tranter 100 e 20 agiunta puncts d’annunzias mo a questa equipa, senza attribuir a l’adversari la differenza tar 157. Il buttun A avra la glista: 3 chartas (20), 4 chartas (50), 5 chartas u quatter chartas da la medema valur (100), quatter novs (150), quatter purs (200). Midai il dumber cun − e + e confermai cun OK. Interrumper na surpiglia betg las midadas. Las annunzias da 50 restan sco stritgs da 50 sin la diagonala e na vegnan betg transfurmadas en stritgs da 100. In’annunzia da 150 vegn mussada cun in stritg da 100 sura ed in stritg da 50 sin la diagonala. Vus pudais tscherner tut las annunzias avant da confermar cun OK, er sche lur total surpassa la finamira: per exempel 70, sche 50 mancan. Suenter la conferma che dat la victoria èn novas annunzias bloccadas. La frizza permetta vinavant da curreger la davosa endataziun.", "help_finish_title": "Terminar ina partida", "help_finish_body": "Ils totals vegnan actualisads automaticamain. L’emprima equipa che cuntanscha u surpassa 1000 u 1500 puncts tenor il modus gudogna. Il victur resta memorisà, er sche ulteriurs puncts vegnan agiuntads. I na dat nagin pari. «Nova partida» memorisescha la partida suenter la conferma e metta ils puncts sin nulla. Ina partida cun puncts u annunzias vegn memorisada er avant la finamira; ina partida vida betg. Ils nums ed il modus restan mantegnids.", "help_history_title": "Consultar la cronologia", "help_history_body": "«Cronologia» mussa las partidas, las datas, las equipas, ils puncts, il modus, ils puncts da las annunzias ed il dumber da match. Tar partidas pli veglias senza dumbrader memorisà cumpara «—». Il victur è l’emprima equipa che ha cuntanschì la finamira. Partidas interruttas avant la finamira n’han nagin victur. Sch’il victur n’era betg memorisà, cumpara «Victur betg memorisà». La crusch stizza ina partida suenter la conferma; «Stizzar la cronologia» stizza tut las partidas suenter la conferma. L’icona sut la crusch cundivida la resumaziun cun puncts, annunzias e match; uschiglio pudais Vus copiar ella. Las partidas giugadas sin la tavla vegnan memorisadas en la medema cronologia cun confermar «Nova partida», cun la remartga «Partida sin la tavla». «Cronologia» sin la tavla avra la glista e «Enavos al gieu» maina enavos a la tavla.", "help_save_title": "Memorisar, cundivider e stampar", "help_save_body": "La partida actuala e la cronologia vegnan memorisadas en il navigatur da quest apparat, senza sincronisaziun cun auters apparats. Stizzar las datas dal navigatur po allontanar questas datas memorisadas. Il buttun da cundivider sper il titel cundivida u copiescha l’adressa dal program, betg las partidas memorisadas. «Tavla» avra la tavla sin l’entir ecran; «Stampar la cronologia» stampa las partidas mussadas.", "help_install_title": "Installar sin il telefon", "help_install_body": "Avri la pagina dal gieu sin il website cun ina connexiun d’Internet ed installai da là, betg da questa pagina d’agid. Sin Android, en Chrome, avri ⋮, lura l’opziun per agiuntar a l’ecran da partenza e l’opziun per installar, u directamain l’opziun per installar l’applicaziun, tenor la versiun. Sin iPhone, en Safari, duvrai il buttun da cundivider (quadrat cun frizza), lura l’opziun per agiuntar a l’ecran da partenza; activai l’opziun per avrir sco applicaziun web, sch’ella vegn purschida, e confermai. Tutgai lura l’icona Chibre Suisse per avrir il gieu. Avri ella l’emprima giada cun Internet per chargiar las datotecas necessarias per l’utilisaziun senza connexiun. Ils texts dals menus dependan da la lingua e da la versiun dal telefon. Suenter la publicaziun sin in website HTTPS, avri il gieu ina giada cun Internet e spetgai fin che tut è chargià. Il gieu, l’agid, las tschintg linguas e la cronologia pon lura vegnir duvrads senza connexiun sin il medem apparat. Colliaziuns externas e trametter cuntegns cundividids dovran ina connexiun.", "help_language_title": "Tscherner la lingua", "help_language_body": "La bandiera svizra avra la selecziun Français, Deutsch, Italiano, Rumantsch u English. La lingua vegn memorisada en quest navigatur e duvrada per il gieu, l’agid, ils messadis e las resumaziuns cundivididas. Ils nums da las persunas participadas na vegnan betg translatads. La versiun rumantscha dovra rumantsch grischun.", "official": "Instrucziuns uffizialas:", "language_question": "Vulais Vus midar la lingua en {language}?", "cards_20": "3 chartas", "cards_50": "4 chartas", "cards_100": "5 chartas", "four_kind": "u quatter chartas da la medema valur", "slate_open": "Avrir la tavla da puncts", "slate_title": "Tavla", "slate_close": "Serrar la tavla", "slate_legend": "100: stritgs sura · 50: diagonala · 20: stritgs sut · rest en cifras. L’autra equipa è orientada vers sia vart da la maisa.", "slate_readout": "{total} puncts: {hundreds} stritgs da 100, {fifties} da 50, {twenties} da 20 e {remainder} puncts restants.", "slate_add": "Agiuntar {value} puncts per {team}", "manual_title": "Agiuntar puncts per {team}", "manual_value": "Puncts d’agiuntar", "cancel": "Interrumper", "add_points": "Agiuntar", "manual_invalid": "Endatai in dumber entir da 2 fin 155 u 257 per in match.", "ann_manual_title": "Annunzias per {team}", "ann_value": "Puncts d’annunzias d’agiuntar", "ann_invalid": "Endatai in dumber entir da puncts pli grond che nulla.", "slate_edit": "Midar la davosa endataziun da {team}", "update": "Midar", "slate_mode_button": "Tavla", "four_nines": "Quatter novs", "four_jacks": "Quatter purs", "slate_game": "Partida sin la tavla", "ann_symbol": "A", "edit_name": "Midar ils nums", "add_round": "Agiuntar a {team} — runda {number}?", "edit_round": "Midar la runda {number} — {team}", "double_toggle": "♠ ♠", "help_slate_use_title": "Duvrar la tavla", "help_slate_use_body": "Avri la tavla per vesair omaduas equipas sin l’entir ecran. Tutgai in num per midar el. Tutgai la surfatscha naira tranter las lingias dal Z per endatar ils puncts: la fanestra mussa l’equipa ed il numer da la runda. Il numer crescha mo suenter la conferma, betg suenter Interrumper u in’annunzia. Endatai 2 fin 155 u 257 per in match. L’adversari survegn automaticamain 157 minus ils puncts endatads; cun 257 survegn el 0. Las lingias dal Z na pon betg vegnir cliccadas. Serrai cun la crusch sura a dretga.", "help_slate_ann_title": "Annunzias sin la tavla", "help_slate_ann_body": "Il buttun A avra las annunzias: 20 per 3 chartas, 50 per 4 chartas, 100 per 5 chartas u quatter chartas da la medema valur, 150 per quatter novs e 200 per quatter purs. Las chartas 9 e J èn illustradas en colur. Tschernì il dumber cun − e + e confermai cun OK: il total vegn agiuntà ina suletta giada. Interrumper na mida nagut. Las annunzias van mo a l’equipa tschernida, senza cumplettar a 157 per l’adversari. Il buttun daventa W en tudestg e M en englais. Cun 950 puncts pudais Vus confermar 70 puncts d’annunzias: Vus arrivais a 1020 e gudagnais. Suenter la victoria n’èn novas annunzias betg permessas.", "help_slate_read_title": "Leger e curreger la tavla", "help_slate_read_body": "Ils stritgs sura valan 100, quels sin la diagonala 50 e quels sut 20; il rest è scrit en cifras. Mintga gruppa da tschintg cuntegna quatter stritgs ed ina diagonala che traversa els. Las annunzias da 50 restan tar ils 50 e las endataziuns da 20 tar ils 20, er sche lur summa cuntanscha 100. In’annunzia da 150 dat in stritg da 100 ed in da 50. La frizza alva ↶ sut ils 20 avra la davosa endataziun da l’equipa cun il dumber gia emplenì; tar ils puncts vegn mussà il numer da la runda. Midar remplazza la valur, curregia ils puncts da l’adversari sche necessari e na creescha betg ina nova runda. Endataziuns pli veglias senza detagls memorisads na pon eventualmain betg vegnir midadas.", "help_slate_double_title": "Palas dubel e fin da la partida", "help_slate_double_body": "Il buttun central «Palas dubel ON/OFF» vala per omaduas equipas. OFF dovra la finamira da 1000 puncts; ON dovra 1500 e dublegia puncts ed annunzias. Endatai adina ils puncts simpels: 100 cunter 57 dat 200 cunter 114, in match da 257 vala 514 ed in’annunzia da 50 vala 100. Midar il modus calculescha er danovamain ils totals gia endatads. L’emprima equipa che cuntanscha u surpassa la finamira gudogna; il messadi cumpara sur la tavla. Nova partida dumonda ina conferma, memorisescha la partida en la cronologia e metta ils puncts sin nulla. Cronologia mussa las partidas memorisadas cun la remartga Partida sin la tavla. Enavos al gieu maina enavos a la tavla.", "round_numbers": "Numer da la runda", "close_victory": "Serrar il panel da victoria"}, "en": {"choose": "Choose a language", "subtitle": "Score sheet", "print": "Print", "new": "New game", "history": "History", "history_title": "Game history", "back": "Back to the game", "clear": "Clear history", "print_history": "🖨️ Print history", "normal": "1000 • normal", "double": "1500 • ♠ ♠", "team_a": "Team Us", "team_b": "Team Them", "us": "Us", "them": "Them", "names": "Enter your names", "ann": "Melds", "ann_title": "Melds {name}", "round_points": "Round scores", "round": "Round", "round_label": "Round {number} {team}", "match": "Match", "help": "how does it work?", "help_title": "How does it work?", "share": "Share", "delete_question": "Delete this game?", "yes": "Yes", "no": "No", "validation": "Enter a whole number from 2 to 155, or 257 for a match.", "full": "All 12 rounds are already filled in.", "win": "🏆 {name} won! {total} points", "empty": "No saved games.", "winner": "Winner", "unfinished": "Game ended before the target was reached", "unknown": "Winner not recorded", "part": "Game", "mode": "Mode", "points": "points", "pts": "pts", "delete_part": "Delete this game", "delete_number": "Delete game {number}", "share_part": "Share this game", "share_number": "Share game {number}", "clear_question": "Permanently delete the entire game history?", "reset_question": "End this game and start a new one?", "summary_copied": "Game summary copied!", "copy_summary": "Copy the game summary:", "link_copied": "Link copied!", "share_unavailable": "Sharing is not available on this device.", "app_description": "Chibre score sheet that can be installed on your phone.", "share_description": "Chibre score sheet", "card_title": "{rank} of {suit}", "nine": "Nine", "jack": "Jack", "spade": "Spades (strongest)", "heart": "Hearts", "diamond": "Diamonds", "club": "Clubs (weakest)", "increase": "Add {value} for {team}", "decrease": "Remove {value} for {team}", "info": "Allowed scores: <b>2 to 155, or 257 for a match</b>. Entering 257 gives the other team <b>0 points</b> and automatically counts one match. Otherwise: <b>157 − entered score</b>. In 1500 mode, the total is doubled once.", "help_start_title": "Start a game", "help_start_body": "Enter the players’ names under “Us” and “Them”, then choose the mode. The sheet starts with 8 rounds. When all visible rows are filled in and neither team has won, one more row appears, up to a maximum of 12 rounds. In normal 1000 mode, round scores and melds count once; the target is 1000 points. In 1500 double spades mode, this application doubles all round scores and melds; the target is 1500 points.", "help_scores_title": "Enter a round score", "help_scores_body": "Enter one team’s score, then confirm or leave the field. The other score is 157 minus the entered score: for example, 100 for Us gives 57 for Them. Allowed values are whole numbers from 2 to 155, or 257 for a match. Each team receives at least 2 points in a normal round. Scores of 0, 1 and 156 to 256 are rejected; 0 is calculated automatically for the team that loses a match.", "help_order_title": "Fill in rounds in order", "help_order_body": "Only the first empty row is available. Later rows stay grey until the preceding row is filled in. Completed rows can still be edited. To correct a round, change one field. To clear it, empty one field and confirm: that round and all later rounds are cleared to keep the rounds in order.", "help_match_title": "Count a match", "help_match_body": "257 gives the other team 0 and adds one match to the counter. If a team wins all the points in a round, enter 257, not 157. The + next to “Match” enters 257 on the next empty row. The − removes that team’s last match and clears its round and all later rounds. Editing or clearing a 257 updates the counter. The 257 points are included in the round scores and are not added again as melds.", "help_ann_title": "Add melds", "help_ann_body": "Use + and − in each team’s melds to count melds worth 20, 50, 100, 150 or 200 points. Their total is added to the round scores. The small 9 and J cards are visual reminders for the 150 and 200 melds. The square M button between 100 and 20 adds meld points to that team only, without awarding the opponent the difference from 157. The M button opens the list: 3 cards (20), 4 cards (50), 5 cards or four of a kind (100), four nines (150), four jacks (200). Adjust quantities with − and +, then confirm with OK. Cancel discards the changes. Melds worth 50 remain as 50-point strokes on the diagonal and are not converted into 100-point strokes. A meld worth 150 is shown as one 100-point stroke at the top and one 50-point stroke on the diagonal. You can select all your melds before confirming with OK, even if their total exceeds the target, for example adding 70 when only 50 are needed. Once that confirmation declares a winner, new meld additions are blocked. The back arrow still lets you correct the last entry.", "help_finish_title": "End a game", "help_finish_body": "Totals update automatically. The first team to reach or exceed 1000 or 1500, depending on the mode, wins. The winner stays recorded even if more points are entered later. There is no draw. After confirmation, “New game” saves the game and resets the scores. A game containing scores or melds is saved even before the target is reached; an empty game is not saved. Names and mode are kept.", "help_history_title": "View game history", "help_history_body": "“History” shows games, dates, teams, scores, mode, meld points and the match counter. Older games without a saved match counter show “—”. The winner is the first team to reach the target. A game stopped before the target has no winner. If the winner was not saved, “Winner not recorded” is shown. The cross deletes one game after confirmation; “Clear history” deletes all games after confirmation. The icon below the cross shares a summary with scores, melds and match counts; if sharing is unavailable, you can copy it. Games played on the slate are saved in the same history when you confirm “New game”, labelled “Slate game”. “History” on the slate opens the list, and “Back to the game” returns to the slate.", "help_save_title": "Saving, sharing and printing", "help_save_body": "The current game and history are saved in this device’s browser, without syncing to other devices. Clearing browser data may delete these saved games. Sharing next to the title shares or copies the application’s address, without sharing saved games. “Slate” opens the full-screen slate; “Print history” prints the displayed games.", "help_install_title": "Install on your phone", "help_install_body": "Open the game page on the website with an Internet connection and install from that page, not from this help page. On Android, in Chrome, open ⋮, then “Add to home screen” and “Install”, or directly “Install app”, depending on the version. On iPhone, in Safari, use Share (the square with an arrow), then “Add to Home Screen”; enable “Open as Web App” if offered and tap “Add”. Then tap the Chibre Suisse icon to launch the game. Open it once with an Internet connection to load the files needed for offline use. Menu labels may vary with your phone’s version. After publishing on an HTTPS website, open the game once with an Internet connection and wait for it to finish loading. The game, help, five languages and history can then be used offline on the same device. External links and sending shared content require a connection.", "help_language_title": "Choose a language", "help_language_body": "The Swiss flag opens the language menu: Français, Deutsch, Italiano, Rumantsch or English. The language is remembered in this browser and applies to the game, help, messages and shared summaries. Players’ names are not translated. The Romansh version uses Rumantsch Grischun.", "official": "Official instructions:", "language_question": "Change the language to {language}?", "cards_20": "3 cards", "cards_50": "4 cards", "cards_100": "5 cards", "four_kind": "or four of a kind", "slate_open": "Open the score slate", "slate_title": "Slate", "slate_close": "Close the slate", "slate_legend": "100: top strokes · 50: diagonal · 20: bottom strokes · remainder as digits. The other team faces the opposite side of the table.", "slate_readout": "{total} points: {hundreds} strokes of 100, {fifties} of 50, {twenties} of 20 and {remainder} remaining points.", "slate_add": "Add {value} points for {team}", "manual_title": "Add points for {team}", "manual_value": "Points to add", "cancel": "Cancel", "add_points": "Add", "manual_invalid": "Enter a whole number from 2 to 155, or 257 for a match.", "ann_manual_title": "Melds for {team}", "ann_value": "Meld points to add", "ann_invalid": "Enter a whole number of points greater than zero.", "slate_edit": "Edit the last entry for {team}", "update": "Update", "slate_mode_button": "Slate", "four_nines": "Four nines", "four_jacks": "Four jacks", "slate_game": "Slate game", "ann_symbol": "M", "edit_name": "Edit names", "add_round": "Add to {team} — round {number}?", "edit_round": "Edit round {number} — {team}", "double_toggle": "♠ ♠", "help_slate_use_title": "Using the slate", "help_slate_use_body": "Open the slate to see both teams full-screen. Tap a name to edit it. Tap the black area between the Z lines to enter a round score: the window shows the team and round number. The number advances only after confirmation, not after Cancel or a meld. Enter 2 to 155, or 257 for a match. The opponent automatically receives 157 minus the entered score; for 257 they receive 0. The Z lines are not clickable. Close the slate using the cross at the top right.", "help_slate_ann_title": "Melds on the slate", "help_slate_ann_body": "The M button opens melds: 20 for 3 cards, 50 for 4 cards, 100 for 5 cards or four of a kind, 150 for four nines and 200 for four jacks. The 9 and J cards are illustrated in colour. Choose quantities with − and +, then press OK to apply the total once. Cancel changes nothing. Melds go only to the chosen team, with no complement to 157 for the opponent. The button is A in French, Italian and Romansh, and W in German. At 950 points, you can confirm 70 meld points: you reach 1020 and win. No new melds can be added after victory.", "help_slate_read_title": "Reading and correcting the slate", "help_slate_read_body": "Top strokes are worth 100, diagonal strokes 50 and bottom strokes 20; the remainder is written as digits. Each group of five consists of four strokes crossed by a diagonal fifth stroke. Melds of 50 stay on the 50 line and scores of 20 on the 20 line, even when their sum reaches 100. A meld of 150 gives one 100 stroke and one 50 stroke. The white ↶ arrow below the 20 line reopens that team’s last entry with its value filled in; score entries also show the round number. Update replaces the entry, adjusts the opponent’s points if needed and does not create a new round. Older entries without saved details may not be editable.", "help_slate_double_title": "Double spades and ending a game", "help_slate_double_body": "The central “Double spades ON/OFF” button applies to both teams. OFF uses a 1000-point target; ON uses 1500 and doubles scores and melds. Always enter single scores: 100 versus 57 becomes 200 versus 114, a 257 match is worth 514 and a meld of 50 is worth 100. Switching modes also recalculates totals already entered. The first team to reach or exceed the target wins; the message appears above the slate. New game asks for confirmation, saves the game in history and resets the points. History shows saved games labelled Slate game. Back to the game returns to the slate.", "round_numbers": "Round number", "close_victory": "Close the victory panel"}};

let currentLanguage="fr";
try{const saved=localStorage.getItem("chibre_language");if(Object.hasOwn(TRANSLATIONS,saved)) currentLanguage=saved;}catch(error){}
function t(key,params={}){
 const template=TRANSLATIONS[currentLanguage][key];
 if(typeof template!=="string") throw new Error("Missing translation: "+currentLanguage+"/"+key);
 return template.replace(/\{(\w+)\}/g,(match,name)=>params[name]??match);
}
function teamName(team){
 const input=document.getElementById(team==="A"?"nameA":"nameB");
 return input&&input.value.trim()?input.value.trim():t(team==="A"?"us":"them");
}
function gameName(game,team){return game["name"+team+"Default"]?t(team==="A"?"us":"them"):String(game["name"+team]??"");}
function gameDate(game){
 if(!game.timestamp) return game.date||"";
 return new Date(game.timestamp).toLocaleString({fr:"fr-CH",de:"de-CH",it:"it-CH",rm:"rm-CH",en:"en-GB"}[currentLanguage]);
}
function applyLanguage(){
 document.documentElement.lang=currentLanguage;
 document.querySelectorAll("[data-i18n]").forEach(el=>el.textContent=t(el.dataset.i18n));
 document.querySelectorAll("[data-i18n-html]").forEach(el=>el.innerHTML=t(el.dataset.i18nHtml));
 for(const attr of ["placeholder","title","aria-label"]){
  document.querySelectorAll("[data-i18n-"+attr+"]").forEach(el=>el.setAttribute(attr,t(el.getAttribute("data-i18n-"+attr))));
 }
 document.querySelectorAll("[data-language]").forEach(el=>el.setAttribute("aria-pressed",String(el.dataset.language===currentLanguage)));
 const flag=document.getElementById("languageFlag");if(flag)flag.setAttribute("aria-label",t("choose"));
 document.title=document.querySelector("article")?t("help_title")+" — Chibre":"Chibre";
 const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=t("app_description");
 const links=document.querySelectorAll("a[data-official]");links.forEach(el=>{const url=new URL(el.href);if(el.dataset.official==="google")url.searchParams.set("hl",currentLanguage==="rm"?"de":currentLanguage);else url.pathname="/"+(currentLanguage==="rm"?"de-ch":currentLanguage==="de"?"de-ch":currentLanguage==="it"?"it-ch":currentLanguage==="en"?"en-gb":"fr-ch")+"/guide/iphone/iphea86e5236/ios";el.href=url.href;});
}
function languageMenuPosition(viewWidth,viewHeight,button,menuHeight){
 const width=Math.min(190,Math.max(0,viewWidth-16));
 const left=Math.max(8,Math.min(button.right-width,viewWidth-width-8));
 const top=Math.max(8,Math.min(button.bottom+6,viewHeight-menuHeight-8));
 return {left,top,width};
}
function positionLanguageMenu(){
 const menu=document.getElementById("languageChoices"),flag=document.getElementById("languageFlag");
 if(!menu||!flag||menu.hidden) return;
 if(window.innerWidth<=600){
  const pos=languageMenuPosition(window.innerWidth,window.innerHeight,flag.getBoundingClientRect(),menu.offsetHeight);
  menu.style.left=pos.left+"px";menu.style.top=pos.top+"px";menu.style.width=pos.width+"px";
 }else{menu.style.left="";menu.style.top="";menu.style.width="";}
}
function closeLanguageMenu(){const menu=document.getElementById("languageChoices"),flag=document.getElementById("languageFlag");if(menu)menu.hidden=true;if(flag)flag.setAttribute("aria-expanded","false");}
function setLanguage(lang){
 if(!Object.hasOwn(TRANSLATIONS,lang)) return;
 currentLanguage=lang;try{localStorage.setItem("chibre_language",lang);}catch(error){}
 closeLanguageMenu();applyLanguage();
 if(typeof render==="function"){winnerShownFor=null;render();if(document.getElementById("slateDialog")?.open)renderSlate();if(document.getElementById("historyPage").style.display==="block")openHistory();}
}
function requestLanguageChange(lang){
 if(lang===currentLanguage || !Object.hasOwn(TRANSLATIONS,lang)){closeLanguageMenu();return;}
 const names={fr:"Français",de:"Deutsch",it:"Italiano",rm:"Rumantsch",en:"English"};
 const dialog=document.getElementById("languageDialog");
 document.getElementById("languageQuestion").textContent=t("language_question",{language:names[lang]});
 dialog.returnValue="no";
 closeLanguageMenu();
 dialog.onclose=()=>{if(dialog.returnValue==="yes")setLanguage(lang);const flag=document.getElementById("languageFlag");if(flag)flag.focus();};
 dialog.showModal();
}
document.addEventListener("DOMContentLoaded",()=>{
 applyLanguage();
 const flag=document.getElementById("languageFlag"),menu=document.getElementById("languageChoices");
 if(flag)flag.addEventListener("click",()=>{menu.hidden=!menu.hidden;flag.setAttribute("aria-expanded",String(!menu.hidden));positionLanguageMenu();});
 document.querySelectorAll("[data-language]").forEach(button=>button.addEventListener("click",()=>{requestLanguageChange(button.dataset.language);}));
 document.addEventListener("click",event=>{if(!event.target.closest(".language-picker"))closeLanguageMenu();});
 document.addEventListener("keydown",event=>{if(event.key==="Escape"&&menu&&!menu.hidden){closeLanguageMenu();flag.focus();}});
});

window.addEventListener("resize",positionLanguageMenu);
window.addEventListener("scroll",positionLanguageMenu,true);
